				(count - len) / sizeof(u32));
	}
}

static void glink_rpm_rx_advance(struct glink_rpm *glink,
				 size_t count)
{
	struct glink_rpm_pipe *pipe = &glink->rx_pipe;
	unsigned int tail;

	tail = readl(pipe->tail);

	tail += count;
	if (tail >= pipe->length)
		tail -= pipe->length;

	writel(tail, pipe->tail);
}

